package org.sleepwell.app;

import android.content.Context;
import android.database.sqlite.SQLiteDatabase;
import androidx.test.platform.app.InstrumentationRegistry;
import org.json.JSONObject;
import org.junit.Test;
import java.io.*;
import java.util.*;
import static org.junit.Assert.*;

/** Uniquely named databases and owned WAVs only. No audio, microphone, service or preferences changes. */
public class SoundLibraryStorageTest {
    private Context context(){return InstrumentationRegistry.getInstrumentation().getTargetContext();}
    private String database(){return "sleepwell-verification-"+UUID.randomUUID()+".db";}
    private File wave(Context c,List<File> owned)throws Exception{File dir=new File(c.getFilesDir(),"clips");assertTrue(dir.isDirectory()||dir.mkdirs());File file=new File(dir,"verification-library-"+UUID.randomUUID()+".wav");NoiseRecorder.writeWave(file,new byte[32000]);owned.add(file);return file;}
    private void clean(Context c,String name,List<File> files){c.deleteDatabase(name);Collections.reverse(files);for(File file:files)if(file.exists())assertTrue(file.delete());}
    private void five(SQLiteDatabase db){
        String[] ddl={"CREATE TABLE alarms(id INTEGER PRIMARY KEY,data TEXT NOT NULL)","CREATE TABLE sessions(id INTEGER PRIMARY KEY,start INTEGER NOT NULL,end INTEGER,note TEXT DEFAULT '',rating INTEGER DEFAULT 0,interrupted INTEGER DEFAULT 0,active_ms INTEGER,clock_changed INTEGER DEFAULT 0,source TEXT NOT NULL DEFAULT 'legacy',origin TEXT NOT NULL DEFAULT 'legacy',zone TEXT NOT NULL DEFAULT '')","CREATE TABLE epochs(id INTEGER PRIMARY KEY,session INTEGER NOT NULL,time INTEGER NOT NULL,movement REAL,noise REAL,light REAL,samples INTEGER,start INTEGER)","CREATE TABLE clips(id INTEGER PRIMARY KEY,session INTEGER NOT NULL,time INTEGER NOT NULL,path TEXT NOT NULL,level REAL,category TEXT NOT NULL DEFAULT 'noise',score REAL NOT NULL DEFAULT 0,duration_ms INTEGER NOT NULL DEFAULT 10000)","CREATE TABLE sound_events(id INTEGER PRIMARY KEY,session INTEGER NOT NULL,time INTEGER NOT NULL,duration_ms INTEGER NOT NULL,category TEXT NOT NULL,score REAL NOT NULL,model TEXT NOT NULL,clip INTEGER)","CREATE INDEX sound_events_session ON sound_events(session,time)","CREATE TRIGGER unlink_sound_clip AFTER DELETE ON clips BEGIN UPDATE sound_events SET clip=NULL WHERE clip=OLD.id; END","CREATE TABLE tracking_pauses(id INTEGER PRIMARY KEY,session INTEGER NOT NULL,start INTEGER NOT NULL,end INTEGER)","CREATE TABLE record_edits(session INTEGER PRIMARY KEY,start INTEGER NOT NULL,end INTEGER NOT NULL,note TEXT NOT NULL DEFAULT '',tags TEXT NOT NULL DEFAULT '[]',awake TEXT NOT NULL DEFAULT '[]',rating INTEGER NOT NULL DEFAULT 0,rated INTEGER NOT NULL DEFAULT 0,updated INTEGER NOT NULL,reverted INTEGER NOT NULL DEFAULT 0)","CREATE TABLE record_create_requests(token TEXT PRIMARY KEY,session INTEGER NOT NULL)"};for(String sql:ddl)db.execSQL(sql);db.execSQL("CREATE INDEX epochs_session ON epochs(session,time)");db.execSQL("CREATE INDEX pauses_session ON tracking_pauses(session,start)");
    }
    @Test public void versionFiveUpgradePreservesEverySeededValueAndExistingWav()throws Exception{
        Context c=context();String name=database();List<File> owned=new ArrayList<>();File audio=wave(c,owned);byte[] before=java.nio.file.Files.readAllBytes(audio.toPath());Alarm alarm=new Alarm(9);alarm.enabled=false;String encoded=alarm.json().toString();
        try{
            assertTrue(c.getDatabasePath(name).getParentFile().isDirectory()||c.getDatabasePath(name).getParentFile().mkdirs());
            try(SQLiteDatabase db=SQLiteDatabase.openOrCreateDatabase(c.getDatabasePath(name),null)){five(db);db.execSQL("INSERT INTO alarms VALUES(9,?)",new Object[]{encoded});db.execSQL("INSERT INTO sessions(id,start,end,note,active_ms,source,origin,zone) VALUES(11,100000,200000,'keep this note',100000,'tracked','local','UTC')");db.execSQL("INSERT INTO epochs VALUES(15,11,160000,.125,.25,2.5,100,100000)");db.execSQL("INSERT INTO clips(id,session,time,path,level,duration_ms) VALUES(12,11,110000,?,.25,1000)",new Object[]{audio.getName()});db.execSQL("INSERT INTO sound_events VALUES(13,11,109000,975,'snoring',.9,'preserved-model',12)");db.setVersion(5);}
            try(Store store=new Store(c,name)){assertEquals(7,store.getReadableDatabase().getVersion());assertEquals(encoded,store.rows("SELECT data FROM alarms").get(0).getString("data"));assertEquals("keep this note",store.rows("SELECT note FROM sessions").get(0).getString("note"));assertEquals(.125,store.rows("SELECT movement FROM epochs").get(0).getDouble("movement"),0);JSONObject event=store.rows("SELECT * FROM sound_events").get(0),clip=store.rows("SELECT * FROM clips").get(0);assertEquals(12,event.getLong("clip"));assertEquals("preserved-model",event.getString("model"));assertEquals(.9,event.getDouble("score"),0);assertEquals(0,event.getInt("favorite"));assertEquals(0,clip.getInt("favorite"));SoundClips.favoriteEvent(store,event,true);assertEquals("ok",store.rows("PRAGMA integrity_check").get(0).getString("integrity_check"));}
            try(Store store=new Store(c,name)){assertEquals(1,store.rows("SELECT favorite FROM sound_events").get(0).getInt("favorite"));assertEquals(0,store.rows("SELECT favorite FROM clips").get(0).getInt("favorite"));}assertArrayEquals(before,java.nio.file.Files.readAllBytes(audio.toPath()));
        }finally{clean(c,name,owned);}
    }
    @Test public void anIndividualFavoriteRetainsSharedAudioWithoutStarringItsOtherEvents()throws Exception{
        Context c=context();String name=database();List<File> owned=new ArrayList<>();try(Store store=new Store(c,name)){
            long session=store.begin(),start=store.rows("SELECT start FROM sessions").get(0).getLong("start");File audio=wave(c,owned);store.clip(session,start+1000,audio.getName(),.1,1000);store.soundEvent(session,start+100,200,"snoring",.9,null);store.soundEvent(session,start+400,200,"speech",.9,null);store.end(session,false,1000,start+1000);List<JSONObject> events=store.rows("SELECT * FROM sound_events ORDER BY time");SoundClips.favoriteEvent(store,events.get(0),true);assertEquals(0,store.rows("SELECT favorite FROM sound_events ORDER BY time DESC LIMIT 1").get(0).getInt("favorite"));SoundClips.prune(c,store,Long.MAX_VALUE,true);assertTrue(audio.exists());assertEquals(1,store.rows("SELECT id FROM clips").size());
            SoundClips.prune(c,store,Long.MAX_VALUE,false);assertFalse(audio.exists());assertTrue(store.rows("SELECT id FROM clips").isEmpty());assertEquals(2,store.rows("SELECT id FROM sound_events").size());assertTrue(store.rows("SELECT id FROM sound_events WHERE clip IS NOT NULL").isEmpty());assertEquals(1,store.rows("SELECT favorite FROM sound_events ORDER BY time LIMIT 1").get(0).getInt("favorite"));
        }finally{clean(c,name,owned);}
    }
    @Test public void durableDeletionSurvivesMissingFilesBlockedUnlinksAndReusedIds()throws Exception{
        Context c=context();String name=database();List<File> owned=new ArrayList<>();try(Store store=new Store(c,name)){
            store.getWritableDatabase().execSQL("INSERT INTO sessions(id,start,end,source,zone) VALUES(1,1000,100000,'tracked','UTC')");File old=wave(c,owned),replacement=wave(c,owned);store.clip(1,11000,old.getName(),.1);JSONObject stale=store.rows("SELECT * FROM clips").get(0);SoundClips.stage(store,stale);store.getWritableDatabase().delete("clips",null,null);store.clip(1,21000,replacement.getName(),.1);try{SoundClips.favorite(store,stale,true);fail("Identity reuse must reject");}catch(IllegalArgumentException expected){}SoundClips.recover(c,store);assertFalse(old.exists());assertTrue(replacement.exists());assertEquals(1,store.rows("SELECT id FROM clips").size());
            File blocked=new File(replacement.getParentFile(),"verification-blocked-"+UUID.randomUUID()+".wav");assertTrue(blocked.mkdir());owned.add(blocked);File child=new File(blocked,"child");assertTrue(child.createNewFile());owned.add(child);store.clip(1,31000,blocked.getName(),.1);JSONObject row=store.rows("SELECT * FROM clips WHERE path=?",blocked.getName()).get(0);try{SoundClips.delete(c,store,row);fail("Blocked unlink must remain pending");}catch(IOException expected){}assertTrue(SoundClips.pending(store,row.getLong("id")));assertTrue(child.delete());assertTrue(blocked.delete());SoundClips.recover(c,store);assertTrue(store.rows("SELECT id FROM clips WHERE path=?",blocked.getName()).isEmpty());assertTrue(store.rows("SELECT * FROM pending_clip_deletes").isEmpty());
            store.getWritableDatabase().execSQL("INSERT INTO sessions(id,start,end,source,zone) VALUES(2,1000,100000,'tracked','UTC')");store.clip(2,41000,replacement.getName(),.1);assertTrue(Records.delete(store,1,Records.get(store,1).updated).isEmpty());SoundClips.recover(c,store);assertTrue("Another night still owns the shared WAV",replacement.exists());assertEquals(1,store.rows("SELECT id FROM clips").size());
            assertTrue(SoundClips.eraseHistory(c,store));assertFalse(replacement.exists());assertTrue(store.rows("SELECT id FROM sessions").isEmpty());assertTrue(store.rows("SELECT * FROM pending_clip_deletes").isEmpty());
        }finally{clean(c,name,owned);}
    }
}
